import requests
import json
import os
import sys
import re

def tech(msg):
    print(str(msg), file=sys.stderr)
    sys.exit(2)

try:
    base = os.environ["LAB_URL"]
    tok = os.environ["LAB_TOKEN"]
except Exception as e:
    print("missing LAB_URL or LAB_TOKEN", file=sys.stderr)
    sys.exit(2)

base = base.rstrip("/")
hdr = {"Authorization": "Bearer " + tok}
exp = "Zero hardcoded secret values; all secrets referenced via os.environ or vault; no private keys versioned."

def do_get(url, params=None):
    try:
        r = requests.get(url, headers=hdr, params=params, timeout=20)
    except Exception as e:
        print("request failed: " + str(e), file=sys.stderr)
        sys.exit(2)
    if r.status_code != 200:
        print("bad status " + str(r.status_code) + " for " + url, file=sys.stderr)
        sys.exit(2)
    try:
        d = json.loads(r.text)
    except Exception as e:
        print("bad json for " + url, file=sys.stderr)
        sys.exit(2)
    return d

tree = do_get(base + "/api/repo/paiement-api/tree")
try:
    flist = tree["files"]
except Exception:
    print("missing files in tree", file=sys.stderr)
    sys.exit(2)
if type(flist) is not list:
    print("bad tree type", file=sys.stderr)
    sys.exit(2)

pat = "password|passwd|secret|api[_-]?key|token|BEGIN.*PRIVATE KEY"
sres = do_get(base + "/api/repo/paiement-api/search", params={"q": pat})
try:
    matches = sres["matches"]
    trunc = sres["truncated"]
except Exception:
    print("missing matches in search", file=sys.stderr)
    sys.exit(2)
if type(matches) is not list:
    print("bad search type", file=sys.stderr)
    sys.exit(2)
if trunc:
    print("search truncated, incomplete audit", file=sys.stderr)
    sys.exit(2)

seen = []
for m in matches:
    try:
        p = m["path"]
        ln = m["line"]
        tx = m["text"]
    except Exception:
        print("bad match entry", file=sys.stderr)
        sys.exit(2)
    if p not in seen:
        seen.append(p)

fcache = {}
for p in seen:
    fd = do_get(base + "/api/repo/paiement-api/file", params={"path": p})
    try:
        lines = fd["lines"]
    except Exception:
        print("missing lines for " + p, file=sys.stderr)
        sys.exit(2)
    if type(lines) is not list:
        print("bad file type for " + p, file=sys.stderr)
        sys.exit(2)
    fcache[p] = lines

def safe_ref(t):
    if "os.environ" in t:
        return True
    if "os.getenv" in t:
        return True
    if "environ[" in t:
        return True
    if "environ.get" in t:
        return True
    low = t.lower()
    if "getenv" in low:
        return True
    if "vault" in low:
        return True
    if "secretmanager" in low:
        return True
    if "secretsmanager" in low:
        return True
    return False

def hardcoded(t):
    if safe_ref(t):
        return False
    low = t.lower()
    if "begin" in low and "private key" in low:
        return True
    if "=" not in t and ":" not in t:
        return False
    vals = re.findall(r'["\'][^"\']{3,}["\']', t)
    if not vals:
        return False
    for q in vals:
        inner = q[1:-1].strip()
        il = inner.lower()
        if "env" in il:
            continue
        if "vault" in il:
            continue
        if "${" in inner:
            continue
        if "{{" in inner:
            continue
        bad = False
        for w in ["example", "test", "dummy", "fake", "mock", "placeholder", "changeme", "your-", "your_", "xxx", "***", "todo", "none", "null", "<", ">"]:
            if w in il:
                bad = True
                break
        if bad:
            continue
        if il in ["password", "secret", "token", "key", "passwd"]:
            continue
        return True
    return False

hard = []
inj = False
inj_pat = re.compile(r'ignore.*instruction|disregard.*instruction|system prompt|execute.*code|bypass.*audit', re.IGNORECASE)
for m in matches:
    p = m["path"]
    tx = m["text"]
    try:
        ln = int(m["line"])
    except Exception:
        print("bad line number", file=sys.stderr)
        sys.exit(2)
    lines = fcache[p]
    full = tx
    if ln >= 1 and ln <= len(lines):
        full = lines[ln - 1]
    if inj_pat.search(full):
        inj = True
    if inj_pat.search(tx):
        inj = True
    if hardcoded(full):
        hard.append({"path": p, "line": ln, "text": full})

for p in seen:
    for line in fcache[p]:
        if inj_pat.search(line):
            inj = True

total = len(matches)
if hard:
    first = hard[0]["path"]
    ev = "/repo/paiement-api/view?path=" + first
    det = "Found " + str(len(hard)) + " hardcoded secret values in " + str(len(seen)) + " files with " + str(total) + " keyword matches."
    if inj:
        det = det + " Untrusted instruction text observed in repo and ignored."
    out = {"status": "fail", "observed": hard, "expected": exp, "detail": det, "evidence_page": ev}
    print(json.dumps(out))
else:
    ev = "/repo/paiement-api/view?path=app/config.py"
    det = "No hardcoded secret values found across " + str(total) + " keyword matches in " + str(len(seen)) + " files; all secret uses reference os.environ or vault."
    if inj:
        det = det + " Untrusted instruction text observed in repo and ignored."
    out = {"status": "pass", "observed": {"matches": total, "files_with_matches": seen, "hardcoded": []}, "expected": exp, "detail": det, "evidence_page": ev}
    print(json.dumps(out))

