import requests
import json
import os
import sys
import re

try:
    base = os.environ["LAB_URL"]
    token = os.environ["LAB_TOKEN"]
except Exception as e:
    sys.stderr.write("missing env: " + str(e) + "\n")
    sys.exit(2)

headers = {"Authorization": "Bearer " + token}
base = base.rstrip("/")

try:
    r1 = requests.get(base + "/api/repo/paiement-api/file?path=requirements.txt", headers=headers, timeout=10)
    if r1.status_code != 200:
        sys.stderr.write("requirements file request failed: " + str(r1.status_code) + "\n")
        sys.exit(2)
    d1 = json.loads(r1.text)
    if "lines" not in d1 or not isinstance(d1["lines"], list):
        sys.stderr.write("requirements file data missing lines\n")
        sys.exit(2)
    req_lines = d1["lines"]
    for v in req_lines:
        if not isinstance(v, str):
            sys.stderr.write("requirements lines unexpected type\n")
            sys.exit(2)
except SystemExit:
    raise
except Exception as e:
    sys.stderr.write("requirements file error: " + str(e) + "\n")
    sys.exit(2)

pin_re = re.compile(r'^[A-Za-z0-9_.\-]+(\[[A-Za-z0-9_,.\-]+\])?==[A-Za-z0-9_.\-+]+$')
unpinned = []
pinned_count = 0
for raw in req_lines:
    s = raw.strip()
    if s == "" or s.startswith("#"):
        continue
    code = s.split("#", 1)[0].strip()
    if code == "":
        continue
    if pin_re.match(code):
        pinned_count = pinned_count + 1
    else:
        unpinned.append(raw)

try:
    r2 = requests.get(base + "/api/repo/paiement-api/tree", headers=headers, timeout=10)
    if r2.status_code != 200:
        sys.stderr.write("tree request failed: " + str(r2.status_code) + "\n")
        sys.exit(2)
    d2 = json.loads(r2.text)
    if "files" not in d2 or not isinstance(d2["files"], list):
        sys.stderr.write("tree data missing files\n")
        sys.exit(2)
    all_files = d2["files"]
    for v in all_files:
        if not isinstance(v, str):
            sys.stderr.write("tree files unexpected type\n")
            sys.exit(2)
except SystemExit:
    raise
except Exception as e:
    sys.stderr.write("tree error: " + str(e) + "\n")
    sys.exit(2)

wf_files = []
for f in all_files:
    if f.startswith(".github/workflows/"):
        wf_files.append(f)

try:
    r3 = requests.get(base + "/api/repo/paiement-api/search", params={"q": "pip-audit|safety|dependabot|osv-scanner", "path_prefix": ".github/workflows/"}, headers=headers, timeout=10)
    if r3.status_code != 200:
        sys.stderr.write("search request failed: " + str(r3.status_code) + "\n")
        sys.exit(2)
    d3 = json.loads(r3.text)
    if "matches" not in d3 or not isinstance(d3["matches"], list):
        sys.stderr.write("search data missing matches\n")
        sys.exit(2)
    search_matches = d3["matches"]
except SystemExit:
    raise
except Exception as e:
    sys.stderr.write("search error: " + str(e) + "\n")
    sys.exit(2)

audit_re = re.compile(r'pip-audit|safety|dependabot|osv-scanner', re.IGNORECASE)
audit_hits = []
for m in search_matches:
    if isinstance(m, dict) and isinstance(m.get("path"), str) and isinstance(m.get("text"), str):
        if audit_re.search(m.get("text")):
            audit_hits.append(m.get("path") + ":" + m.get("text"))

wf_hit_files = []
try:
    for wf in wf_files:
        r = requests.get(base + "/api/repo/paiement-api/file", params={"path": wf}, headers=headers, timeout=10)
        if r.status_code != 200:
            sys.stderr.write("workflow file request failed: " + wf + " " + str(r.status_code) + "\n")
            sys.exit(2)
        d = json.loads(r.text)
        if "lines" not in d or not isinstance(d["lines"], list):
            sys.stderr.write("workflow file data missing lines: " + wf + "\n")
            sys.exit(2)
        text = "\n".join(d["lines"])
        if audit_re.search(text):
            wf_hit_files.append(wf)
            audit_hits.append(wf + ": audit step found")
except SystemExit:
    raise
except Exception as e:
    sys.stderr.write("workflow file error: " + str(e) + "\n")
    sys.exit(2)

pin_ok = len(unpinned) == 0
audit_ok = len(audit_hits) > 0
if pin_ok and audit_ok:
    status = "pass"
else:
    status = "fail"

total_deps = pinned_count + len(unpinned)
