                        cur_success_ex = line.strip()
                if not cur_failure:
                    if failure_pat.search(window):
                        cur_failure = True
                        cur_failure_ex = line.strip()
        if cur_success:
            if not any_success:
                first_success_ex = cur_success_ex
            any_success = True
        if cur_failure:
            if not any_failure:
                first_failure_ex = cur_failure_ex
            any_failure = True
        if cur_success and cur_failure:
            found_both_path = cur_path
            found_both_success_ex = cur_success_ex
            found_both_failure_ex = cur_failure_ex
    if found_both_path != "":
        best_path = found_both_path
        best_success = True
        best_failure = True
        best_success_ex = found_both_success_ex
        best_failure_ex = found_both_failure_ex
    else:
        best_path = files_data[0]["path"]
        for fd in files_data:
